style.css:
/* Light Brown and Dark Brown YouTube Theme */
@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("youtube.com") {
/* General Background */
  body {
    background-color: #d9c4a1 !important; /* Light brown */
    color: #4d3c2e !important; /* Dark brown */
    background-image: url('https://www.toptal.com/designers/subtlepatterns/patterns/paper-fibers.png'); /* Subtle dark brown wallpaper */
    background-size: cover !important;
  }

  #container, #masthead-container, #content {
    background-color: #d9c4a1 !important;
    color: #4d3c2e !important;
  }

  /* Navigation Bar */
  #masthead {
    background-color: #4d3c2e !important;
    color: #d9c4a1 !important;
    border-bottom: 2px solid #b3986d !important;
  }

  /* Sidebar */
  #guide {
    background-color: #4d3c2e !important;
    color: #d9c4a1 !important;
  }

  ytd-mini-guide-entry-renderer, ytd-guide-entry-renderer {
    color: #d9c4a1 !important;
  }

  ytd-guide-entry-renderer:hover, 
  ytd-mini-guide-entry-renderer:hover {
    background-color: #b3986d !important;
    color: #4d3c2e !important;
  }

  /* Video Thumbnails and Titles */
  ytd-thumbnail, ytd-thumbnail-overlay {
    background-color: #4d3c2e !important;
  }

  a.yt-simple-endpoint.style-scope.ytd-video-renderer {
    color: #4d3c2e !important;
  }

  a.yt-simple-endpoint.style-scope.ytd-video-renderer:hover {
    color: #b3986d !important;
  }

  /* Player Area */
  .html5-video-container, 
  #movie_player {
    background-color: #4d3c2e !important;
  }

  /* Progress Bar */
  .ytp-play-progress {
    background: url('https://media.giphy.com/media/3b8Ph443t8EeAvgSVj/giphy.gif') repeat-x !important;
    height: 8px !important;
  }

  .ytp-scrubber-bar {
    background-color: #4d3c2e !important;
  }

  .ytp-progress-bar-container {
    background-color: #b3986d !important;
  }

  /* Comments Section */
  #comments {
    background-color: #d9c4a1 !important;
    color: #4d3c2e !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 8px;
    background-color: #4d3c2e;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #b3986d;
    border-radius: 4px;
  }

  /* Buttons and Links */
  a, .yt-simple-endpoint, .style-scope.ytd-button-renderer {
    color: #4d3c2e !important;
  }

  .yt-simple-endpoint:hover, 
  .style-scope.ytd-button-renderer:hover {
    color: #b3986d !important;
  }

  /* Search Box */
  #search {
    background-color: #d9c4a1 !important;
    color: #4d3c2e !important;
    border: 1px solid #b3986d !important;
  }

  #search:hover, #search:focus {
    border-color: #4d3c2e !important;
  }

  /* Logo */
  ytd-topbar-logo-renderer {
    filter: brightness(0.8);
  }
}
